// Requires patchLibrary's per-model peer hooks. Only the H8 table differs.
export function encodeCMContextDual(data:Uint8Array, context:'bin-stride4'|'wp-token3') {
  if(context!=='bin-stride4'&&context!=='wp-token3')throw Error('only H8-compatible contexts may share')
